use std::sync::atomic::{AtomicBool, Ordering};

static BUSY: AtomicBool = AtomicBool::new(false);

fn enter() -> bool {
    BUSY.compare_exchange(false, true, Ordering::Acquire, Ordering::Relaxed).is_ok()
}

fn leave() {
    BUSY.store(false, Ordering::Release);
}

